-- Seed Framework Data for Dolphins21
INSERT OR REPLACE INTO framework_domains (id, name, description, sort_order) VALUES ('TC1', 'Building Relationships', '', 1);
INSERT OR REPLACE INTO framework_domains (id, name, description, sort_order) VALUES ('TC2', 'Personal and Professional Growth and Development', '', 2);
INSERT OR REPLACE INTO framework_domains (id, name, description, sort_order) VALUES ('TC3', 'Mentoring through Advisory', '', 3);
INSERT OR REPLACE INTO framework_domains (id, name, description, sort_order) VALUES ('TC4', 'Designing for Engagement and Equity', '', 4);
INSERT OR REPLACE INTO framework_domains (id, name, description, sort_order) VALUES ('TC5', 'Facilitating Personalized Learning', '', 5);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC1.1', 'TC1', 'Implement trauma-informed and restorative practices', 'I can interact with students in a fair and equitable manner and consistently implement trauma-informed and restorative practices to support my students.', 1);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC1.2', 'TC1', 'Create opportunities for relationship building', 'I can create opportunities for students to build relationships with me and with each other and to consider multiple perspectives and manage conflict.', 2);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC1.3', 'TC1', 'Value and practice culturally responsive teaching', 'I value students’ cultural and linguistic backgrounds and experiences and view this knowledge as capital upon which I can build.', 3);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC1.4', 'TC1', 'Engage families and the community', 'I engage families and community members to support students'' learning and to grow students'' personal and professional networks.', 4);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC1.5', 'TC1', 'Collaborate with and support colleagues', 'I can collaborate with, support, and seek help from my colleagues while adhering to norms and managing conflict as it arises.', 5);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC2.1', 'TC2', 'Seek and embrace challenges and take risks', 'I can overcome personal barriers to be able to seek academic challenges and take risks to pursue learning and improved outcomes for students.', 1);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC2.2', 'TC2', 'Persevere through setbacks', 'I can persevere through significant academic and non-academic setbacks or failures and I use mistakes and failures as opportunities for learning and growth.', 2);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC2.3', 'TC2', 'Adopt an innovative mindset', 'I strongly believe in the mission and vision of my school and I understand that adopting an innovative mindset requires patience, time, perseverance through failure, and consistently challenging my traditional beliefs about the purpose of school.', 3);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC2.4', 'TC2', 'Seek feedback, support, and resources', 'I consistently seek out feedback and am comfortable asking for help when I need it.', 4);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC2.5', 'TC2', 'Set goals and reflect on personal and professional growth', 'I set measurable goals for my personal and professional development and use a continuous improvement process to gather data, reflect on my progress, and apply my learning.', 5);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC2.6', 'TC2', 'Practice self-care and build emotional intelligence', 'I practice self-care and continue to work on my emotional capacity to care for students who are high need.', 6);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC2.7', 'TC2', 'Commitment to professional learning and leadership', 'I seek opportunities to deepen my professional practice and to take on a leadership role.', 7);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC2.8', 'TC2', 'Effective use of technology', 'I am comfortable using and supporting others in using a variety of technology and I seek new types of technology to learn and introduce to my students.', 8);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC3.1', 'TC3', 'Nurture trusting and meaningful relationships with students', 'I can nurture trusting and meaningful relationships with and among the students in my advisory.', 1);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC3.2', 'TC3', 'Nurture trusting relationships with families', 'I can nurture trusting relationships with the families of each student in my advisory and proactively engage families in a team effort to support their child''s social, emotional, and academic growth and progress.', 2);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC3.3', 'TC3', 'Build community and ownership', 'I can design, adapt, and/or facilitate activities that allow students to build community, engage in meaningful conversations, and take ownership of their school experience.', 3);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC3.4', 'TC3', 'Monitor data and appropriately intervene', 'I can regularly and consistently monitor the academic, attendance, and behavior data for the students in my advisory and provide interventions when necessary', 4);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC3.5', 'TC3', 'Hold regular one-to-one conferences', 'I can facilitate one-to-one conferences with students to support their academic and personal progress and growth.', 5);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC3.6', 'TC3', 'Provide opportunities for growth in Personal Development and Habits of Success competencies', 'I provide students with ample opportunities to monitor and reflect on their Personal Development goals and to evidence the Habits of Success competencies at the highest levels.', 6);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC3.7', 'TC3', 'Support post-secondary planning', 'I can support students in developing an actionable and realistic post-secondary plan and provide support, feedback, and resources to help students successfully implement their plans.', 7);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC4.1', 'TC4', 'Authentic problem frame or question', 'I can design studios that challenge students to wrestle with a complex and authentic problem or question.', 1);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC4.2', 'TC4', 'Culminating performance tasks aligned to competencies', 'I can design culminating performance tasks in alignment with target competencies that address the problem frame of my studio.', 2);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC4.3', 'TC4', 'Engaging launch', 'I can design an engaging launch for my studio that clearly communicates the "why" and gives a compelling reason for students to engage in the content and learning while also creating a shared experience and building a shared understanding.', 3);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC4.4', 'TC4', 'Investigate the problem', 'I can use the backwards design process to deconstruct my culminating task and to design learning experiences that allow my students to investigate the problem from a variety of perspectives in an authentic way.', 4);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC4.5', 'TC4', 'Impact on authentic audience', 'I can support my students in applying their learning to make a real impact on an authentic audience.', 5);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC4.6', 'TC4', 'Designing for daily facilitation', 'I can use multiple forms of data to inform my daily facilitation plan and to design activities and mini-lessons that meet the individual needs of my students.', 6);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC5.1', 'TC5', 'Safe, structured, and flexible learning environment', 'I can establish a safe, structured, and flexible learning environment for a diverse population of students.', 1);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC5.2', 'TC5', 'Performance-based and formative assessment aligned to the competencies and continua', 'I can communicate clear and measurable learning targets and outcomes and design performance-based and formative assessments aligned to the competencies and continua.', 2);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC5.3', 'TC5', 'Higher level thinking and high quality content', 'I can engage students in higher level thinking, questioning, and synthesis through high quality, meaningful, and relevant content presented from multiple perspectives.', 3);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC5.4', 'TC5', 'Scaffolding and differentiation', 'I can set rigorous expectations for students while providing scaffolds and supports so that students across all differences can access the learning.', 4);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC5.5', 'TC5', 'Personalization', 'I can personalize learning for students by tailoring tasks to students'' levels, needs, and interests, by providing cognitive choice, and by encouraging students to take ownership of their learning.', 5);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC5.6', 'TC5', 'High quality work through feedback and revision', 'I can set expectations for high quality work products through the use of self-assessment, goal-setting, feedback, and revision cycles.', 6);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC5.7', 'TC5', 'Use systems to organize, manage, and analyze data to inform instruction', 'I can manage, incorporate, collect, and analyze a variety of data to improve my practice and to improve engagement and outcomes for all students.', 7);
INSERT OR REPLACE INTO framework_competencies (id, domain_id, name, guiding_question, sort_order) VALUES ('TC5.8', 'TC5', 'Enhance learning with digital tools', 'I can use technology to enhance teaching and learning, build digital fluency, and create new products.', 8);
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.1-IND-1', 'TC1.1', 1, 'I establish my expectations for my learning environment.', 'I establish equitable expectations for my learning environment and hold students accountable to those expectations.', 'I collaborate with my students to create equitable expectations for our learning environment and we hold each other accountable for those expectations.', 'My students independently collaborate to create equitable expectations for our learning environment and hold each other accountable for those expectations.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.1-IND-2', 'TC1.1', 2, 'I am not always aware of the impact of trauma on my students'' behavior and I sometimes unintentionally trigger students and escalate behaviors.', 'I am aware of how trauma can impact my students and I try not to trigger or escalate behaviors. I sometimes need strategies to support me when students are triggered.', 'I understand that students have varying traumatic experiences and I am aware of how students’ trauma may influence their behaviors. In the moment, I make efforts to prevent situations that might cause harm or trigger students. I am consistently effective in my use of de-escalation strategies when students are triggered.', 'I understand that students have varying traumatic experiences and I am aware of how students’ trauma may influence their behaviors. I proactively make efforts to prevent situations that might cause harm or trigger students. I am consistently effective in my use of de-escalation strategies when students are triggered.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.1-IND-3', 'TC1.1', 3, 'I am sometimes triggered by the words and behaviors of certain students and may respond to them in a negative way that causes harm.', 'I recognize when I am triggered by a student''s words or behavior and am learning how to depersonalize those feelings so that I can respond to students in a positive way that respects their dignity.', 'I almost always interact with students in a fair and equitable manner. When addressing student behavior, I use language that respects students'' dignity and is sensitive to individual student needs.', 'I always interact with students in a fair and equitable manner. When addressing student behavior, I use language that respects students'' dignity and is sensitive to individual student needs.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.1-IND-4', 'TC1.1', 4, 'I do not use restorative practices responsively (repairing harm and restoring relationships) to manage student behavior. I am sometimes frustrated by the lack of more traditional consequences.', 'I sometimes use restorative practices responsively (repairing harm and restoring relationships) to manage student behavior and am starting to implement proactive strategies.', 'I use restorative practices, both proactively (building relationships and developing community) and responsively (repairing harm and restoring relationships).', 'I consistently and effectively use restorative practices, both proactive (building relationships and developing community) and responsive (repairing harm and restoring relationships).');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.2-IND-1', 'TC1.2', 1, 'I do not often prioritize relationship-building as a tool for student engagement and learning.', 'I am able to build relationships with some students, but struggle to create opportunities for relationship-building with all of my students.', 'I create opportunities for my students to build relationships with me.', 'I consistently create opportunities for my students to build relationships with me and with each other.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.2-IND-2', 'TC1.2', 2, 'My relationships with students are heavily based either on accountability or on care/support and I struggle to find the balance between the two.', 'I understand that students need both accountability and care/support but I struggle to find the balance between the two.', 'My interactions with students reflect a genuine ethic of care balanced with accountability which creates an environment where all students feel known, valued, and safe.', 'My interactions with students reflect a genuine ethic of care balanced with accountability that is sensitive to the individual needs of each student, which creates an environment where all students feel known, valued, and safe.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.2-IND-3', 'TC1.2', 3, 'I do not always know how to support students in considering multiple perspectives to build relationships across dimensions of difference.', 'I sometimes provide my students with opportunities to consider multiple perspectives in order to build relationships across dimensions of difference.', 'I teach my students to consider multiple perspectives and I provide students with the opportunity and support to reflect on their own assumptions and beliefs in order to build stronger relationships across dimensions of difference.', 'I teach my students to consider multiple perspectives and I provide students with the opportunity and support to reflect on their own assumptions and beliefs and to be successful working across dimensions of difference (i.e. varied student groupings, collaborative tasks, problem solving challenges, discussions).');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.2-IND-4', 'TC1.2', 4, 'I struggle to help students identify and manage conflict and/or don''t think I should get involved in student conflicts', 'I support students in using some strategies to engage in, manage, and resolve conflicts (e.g. active listening, seek to understand, check assumptions etc.), but am not always successful.', 'I support students in using a variety of strategies to engage in, manage, and resolve conflicts (e.g. active listening, seek to understand, check assumptions etc.).', 'My students independently use a variety of strategies to engage in, manage, and resolve conflicts (e.g. active listening, seek to understand, check assumptions etc.).');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.3-IND-1', 'TC1.3', 1, 'I feel uncertain about how to think about my own assumptions, values, biases, privilege, and beliefs and I sometimes feel defensive and attacked when I engage in dialogue about racial identity development and culturally responsive instructional practices.', 'Others help me to reflect on my own assumptions, values, biases, privilege, and beliefs. I am learning to manage my feelings to fully engage in racial identity development and culturally responsive instructional practices.', 'I reflect on my own assumptions, values, biases, privilege, and beliefs and understand how my experiences have shaped my views. I sometimes seek out opportunities for feedback and growth in my own racial identity development and culturally responsive instructional practices.', 'I critically analyze my own assumptions, values, biases, privilege, and beliefs and understand how my experiences have shaped my views. I always seek out opportunities for feedback and growth in my racial identity development and culturally responsive teaching.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.3-IND-2', 'TC1.3', 2, 'I understand my students come from diverse backgrounds but I don''t always know how to leverage and accommodate that diversity.', 'I understand my students come from diverse backgrounds and I attempt to scaffold and accommodate learning differences, but I am still learning about how to build on student diversity in an asset-based way', 'I understand that learning about the cultures and languages of individual students allows me to connect to my students'' experiences.', 'I understand that learning about the cultures and languages of individual students allows me to build upon, connect to, and value their existing knowledge and experiences.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.3-IND-3', 'TC1.3', 3, 'I don''t always know how to select content and instructional materials that reflect the racial, ethnic, and/or cultural diversity of my students.', 'I sometimes select content and instructional materials that reflect the racial, ethnic, and/or cultural diversity of my students.', 'I select content and instructional materials that reflect the racial, ethnic, and cultural diversity of my students.', 'I select content and instructional and materials that reflect the racial, ethnic, and cultural diversity of my students. I encourage students to make cultural contributions to the curriculum.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.3-IND-4', 'TC1.3', 4, 'I don''t always recognize how my words and actions impact different students.', 'I understand that my words and actions may have different impacts on different students and am sometimes aware of this impact.', 'I establish and maintain an environment that is sensitive and respectful for the entire, diverse population of students.', 'My students and I hold each other accountable for establishing and maintaining an environment that is sensitive and respectful for the entire, diverse population of students.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.3-IND-5', 'TC1.3', 5, 'I need to pay more attention to how I display students'' work that celebrates the cultural diversity of my students.', 'I sometimes display students'' work that celebrates the cultural diversity of my students.', 'I often select and display student work that celebrates and reflects the diversity of my students and is respectful to individual and community context.', 'My students and I work together to regularly select and display student work that celebrates and reflects the diversity and individualism of students in my learning environment and is respectful to individual and community context.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.4-IND-1', 'TC1.4', 1, 'I most often use the same method of communication to engage families.', 'I engage with families using a variety of communication strategies.', 'I effectively engage families using a variety of culturally responsive practices and communication strategies.', 'I effectively engage families using a variety of culturally responsive practices and communication strategies that result in increased and/or more meaningful student and family participation and engagement.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.4-IND-2', 'TC1.4', 2, 'I try to build relationships with few of my students'' families.', 'I work to build relationships with some of my students'' families to support student learning.', 'I work to build relationships with most of my students'' families, and am starting to build relationships with some community members, businesses, and others outside of the school to support student learning.', 'I have strong relationships with most of my students'' families as well as community members, businesses, and others outside of the school to support communities of practice that enhance student learning.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.4-IND-3', 'TC1.4', 3, 'I mention to students the need to build personal and professional networks but do not know how to support them in building these networks.', 'I talk to my students about the need to build personal and professional networks and explain a few ways they should be doing that.', 'I am explicit with my students about the value of building personal and professional networks and I make suggestions for people my students can connect with to build these networks.', 'I am explicit with my students about the value of building personal and professional networks and I am actively connecting community members and business partners with my students to provide opportunities to build these networks.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.5-IND-1', 'TC1.5', 1, 'I am not always aware when I have broken a school norm. I am uncomfortable pointing out when one of my colleagues has broken a norm.', 'I adhere to our school norms and realize when I have broken a norm but am reluctant to address when someone else has broken a norm.', 'I adhere to our school norms and sometimes address when a norm is broken by myself or one of my colleagues.', 'I always adhere to our school norms and am comfortable addressing when a norm is broken by myself or one of my colleagues.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.5-IND-2', 'TC1.5', 2, 'I would rather work alone and do not feel comfortable giving feedback to my colleagues.', 'I support my colleagues in implementing their ideas.', 'I support my colleagues in implementing their ideas and in providing them feedback when asked.', 'I support my colleagues in implementing their ideas and in providing them with solicited and unsolicited feedback.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.5-IND-3', 'TC1.5', 3, 'I rarely seek support and am uncomfortable asking for help to improve my own ideas and instructional practices.', 'I seek out the support of a few trusted colleagues when I need help to improve my own ideas and instructional practices.', 'I seek out support and feedback from the colleagues I work closely with in order to improve my own ideas and instructional practices.', 'I seek out the support and feedback of many different colleagues as well as other members of my professional network in order to improve my own ideas and instructional practices.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC1.5-IND-4', 'TC1.5', 4, 'I am uncomfortable engaging in any conflict or sometimes unproductively engage in conflict.', 'I am learning to engage in constructive conflict and need more strategies to engage effectively (e.g. active listening, seek to understand, check assumptions, etc).', 'I effectively use a variety of strategies to engage in, manage, and resolve conflicts (e.g. active listening, seek to understand, check assumptions etc.).', 'I effectively use a variety of strategies to engage in, manage, and resolve conflicts (e.g. active listening, seek to understand, check assumptions etc.) and regularly support my colleagues in resolving conflicts.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.1-IND-1', 'TC2.1', 1, 'I rarely take on new challenges or risks to pursue learning.', 'With encouragement, I sometimes take on new challenges and risks to pursue learning.', 'I seek new challenges and I take risks to pursue learning.', 'I strategically seek new challenges and take risks (i.e. to address an enduring problem, to implement new technology, to apply feedback from students to improve engagement) to improve outcomes for students.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.1-IND-2', 'TC2.1', 2, 'I worry too much about what could go wrong or how I might fail and I am unable to get past the worry to take a risk.', 'I worry about what could go wrong or how I might fail, but with encouragement, I can sometimes get past the worry to take a risk.', 'When I begin to worry, I try to reframe my thinking to a wondering instead of a worry about what might happen if I take a risk.', 'I catch myself when I begin to worry and I can immediately shift my thinking to wondering and curiosity about what might happen if I take a risk.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.1-IND-3', 'TC2.1', 3, 'I struggle to identify my personal barriers (mindset, beliefs, circumstances) that inhibit my ability to take risks.', 'I can identify my personal barriers (mindset, beliefs, circumstances) that inhibit my ability to take risks.', 'I can identify and reflect on my personal barriers (mindset, beliefs, circumstances) that inhibit my ability to take risks.', 'I analyze and overcome personal barriers (mindset, beliefs, circumstances) that could inhibit taking risks.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.2-IND-1', 'TC2.2', 1, 'I often give up at the slightest setback or failure.', 'I can sometimes recover from setbacks or failure.', 'I can most often persevere through setbacks or failure.', 'I consistently persevere through significant academic and non-academic setbacks or failures.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.2-IND-2', 'TC2.2', 2, 'I view failure as a reflection of my inherent ability and I do not think effort or practice will help me get better at a skill, improve the quality of my work, or improve my performance.', 'I believe effort and practice can help me get better at some things, but no matter how much effort I put in, there are some parts of my work or performance that I believe I will never be good at.', 'I understand the importance of effort and practice as it relates to getting better at skills, improved work quality, or performance and I believe I can continually improve myself both personally and professionally.', 'I demonstrate how improved performance and work quality are gained through effort, persistence, patience, and time.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.3-IND-1', 'TC2.3', 1, 'I express a belief in the mission and vision of my school but my practices may present otherwise.', 'I believe in the mission and vision of my school but am sometimes unsure of how we will succeed.', 'I believe in the mission and vision of my schooI. I am motivated to try to be part of the reason we are successful.', 'I strongly believe in the mission and vision of my schooI. I have a strong sense of purpose and motivation and I believe that I am an essential part of our ability to succeed.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.3-IND-2', 'TC2.3', 2, 'I am often unaware of my traditional beliefs and mindsets about education until others bring it to my attention.', 'I am somewhat aware of my traditional beliefs and mindsets about education and the purpose of school but I don''t always realize how and when they interfere with my ability to innovate or change.', 'I am aware of my traditional beliefs and mindsets about education and the purpose of school and I reflect on them to understand how they influence or interfere with my ability to innovate or change.', 'I am aware of and consistently challenge my traditional beliefs and mindsets about education and the purpose of school.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.3-IND-3', 'TC2.3', 3, 'I expect to see the desired outcomes of our innovation happen quickly and when they do not, I fall back on traditional and familiar structures and practices.', 'I understand that innovation and change take time, but when I do not see short term results, I start to fall back on traditional and familiar structures and practices.', 'I understand that innovation and change are not easy and take time and perseverance.', 'I understand that an innovative mindset requires commitment and that innovation and change are not easy and take time and perseverance.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.3-IND-4', 'TC2.3', 4, 'I am hesitant to implement many of our innovative initiatives and wait for others to have some success before I try.', 'I try to implement some of our innovative initiatives but am not confident in what I am doing.', 'I push our innovative initiatives forward and am willing to pilot something new.', 'I consistently push our innovative initiatives forward and am always willing to pilot something new and to support my colleagues who are struggling.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.3-IND-5', 'TC2.3', 5, 'I am not confident talking to students and families about our innovative initiatives and struggle to explain why we are implementing these changes.', 'I attempt to talk to students and families about the "why" of our innovative initiatives but struggle to clearly explain all of the different components of our innovation.', 'I can clearly communicate the "why" and the "how" of our innovative initiatives to students and families.', 'I can clearly communicate the "why" and the "how" of our innovative initiatives and am comfortable talking to all stakeholders in a variety of settings (e.g. back to school nights, board meetings, district/state meetings, when other schools visit).');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.3-IND-6', 'TC2.3', 6, 'When problems arise as we implement our innovation, I usually attribute the problem to some or all of the elements of our innovation (i.e. CBE, Beacon, studio design) instead of trying to work with others to determine and implement solutions.', 'When problems arise as we implement our innovation, I start to have doubts about some of the elements of our innovation (i.e. CBE, Beacon, studio design).', 'When problems arise as we implement our innovation, I seek to understand why without blaming the innovation itself.', 'When problems arise as we implement our innovation, I seek to understand why, and actively work with others to determine and implement solutions.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.4-IND-1', 'TC2.4', 1, 'I struggle to be open when receiving criticism and feedback.', 'I can be open to feedback and criticism, but only from certain trusted individuals.', 'I sometimes seek out and use feedback and criticism (when appropriate) from a variety of individuals (i.e. administrators, colleagues, students) to improve my practice and help me grow both professionally and personally.', 'I always seek out and use feedback and criticism (when appropriate) from a wide variety of individuals (i.e. administrators, colleagues, students) to improve my practice, shift my thinking, and help me grow both professionally and personally.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.4-IND-2', 'TC2.4', 2, 'I do not ask for help because I am afraid of appearing inept or incompetent.', 'I will ask for help, but only from certain trusted individuals.', 'I am sometimes comfortable asking for help because I know we are all learners and have room for improvement.', 'I am comfortable asking for help and I view my own lack of knowledge or competence as an invitation to learn and to grow.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.4-IND-3', 'TC2.4', 3, 'I have a limited knowledge of resources both within my school, district, and online. I rarely seek out or use these resources to build my professional knowledge.', 'I have some knowledge of resources both within my school, district, and online. I occasionally use these resources to build my professional knowledge.', 'I have considerable knowledge of resources both within my school, district, and online, as well as in the community. I consistently use these resources to build my professional knowledge.', 'I have an extensive knowledge of resources both within my school, district, and online, as well as in the community. I strategically use these resources to build my professional knowledge and extend and enhance learning opportunities for my students.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.5-IND-1', 'TC2.5', 1, 'When prompted by others, I reflect on the effectiveness of lessons, tasks, studio design, and interactions with students, but my reflections are not always as objective as I would like them to be.', 'When prompted by others, I reflect on the effectiveness of lessons, tasks, studio design, and interactions with students.', 'I sometimes reflect on the effectiveness of lessons, tasks, studio design, and interactions with students.', 'I regularly reflect on the effectiveness of lessons, tasks, studio design, and my interactions with students.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.5-IND-2', 'TC2.5', 2, 'I do not really provide opportunities for students to give me feedback.', 'I occasionally ask my students for feedback on my teaching practices or my learning environment.', 'I sometimes ask my students for feedback on my teaching practices, the learning environment, and my relationships.', 'I regularly involve my students in giving me feedback and in helping me reflect on my teaching practices, my relationships, and the learning environment.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.5-IND-3', 'TC2.5', 3, 'When promoted and with support, I set measurable goals (i.e. SMART goals) for my personal and professional development that are based on my self-assessment on the teacher competencies.', 'With support, I set measurable goals (i.e. SMART goals) for my personal and professional development that are based on my self-assessment on the teacher competencies. I occasionally track my progress towards achieving my goals.', 'I set measurable goals (e.g., SMART goals) for my personal and professional development that are based on my thorough self-assessment on the teacher competencies. I consistently track my progress towards achieving my goals and I reflect on my progress.', 'I set measurable goals (e.g., SMART goals) for my personal and professional development that are based on my thorough self-assessment on the teacher competencies. I consistently track my progress towards achieving my goals and I reflect on and share my progress with others.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.6-IND-1', 'TC2.6', 1, 'I often blame myself or others when I feel overwhelmed or unsuccessful.', 'I am aware that increasing my emotional intelligence (self-awareness, self-regulation, motivation, empathy, and social skills) will improve my sense of well-being, but I don''t always know how to do that.', 'I seek out resources and support in order to increase my emotional intelligence (self-awareness, self-regulation, motivation, empathy, and social skills).', 'I actively seek out resources, support, and feedback in order to increase my emotional intelligence (self-awareness, self-regulation, motivation, empathy, and social skills).');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.6-IND-2', 'TC2.6', 2, 'I am not familiar with the concept of secondary trauma or the corresponding symptoms.', 'I am somewhat familiar with the concept of secondary trauma and compassion fatigue but I am not always aware of when I am experiencing those symptoms.', 'I understand that I may experience secondary trauma or compassion fatigue from working with students impacted by trauma and I know the symptoms to watch for.', 'I understand that I may experience secondary trauma or compassion fatigue from working with students impacted by trauma and I try to care for myself when those symptoms occur.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.6-IND-3', 'TC2.6', 3, 'I do not have a set of strategies that I regularly use to improve my sense of well-being.', 'I sometimes utilize healthy strategies (e.g. mindfulness, meditation, exercise) to improve my sense of well-being outside of the workplace.', 'I consistently utilize healthy strategies (e.g. mindfulness, meditation, exercise) to improve my sense of well-being outside of the workplace.', 'I consistently utilize healthy strategies (e.g. mindfulness, meditation, exercise) to improve my sense of well-being and take good care of myself both onsite and away from the work environment.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.6-IND-4', 'TC2.6', 4, 'I don''t always feel comfortable going to colleagues or friends for help or support.', 'I have a few trusted colleagues and friends that I can reach out to when I need support.', 'I have a positive network of colleagues and friends that I regularly reach out to for support.', 'I have a positive network of colleagues and friends that I regularly reach out to for support and they hold me accountable to my self-care goals.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.7-IND-1', 'TC2.7', 1, 'I only attend required professional development (PD). I prefer to spend my planning /PD time working independently.', 'I will occasionally attend a voluntary PD session or workshop but don''t often seek out these opportunities. I will collaborate with others but I am sometimes uncomfortable because I don''t think I can contribute as much or as well as others.', 'I seek opportunities to grow professionally and to collaborate with and learn from others.', 'I seek professional opportunities that challenge my thinking, deepen my practice, and allow me to collaborate with and learn from others.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.7-IND-2', 'TC2.7', 2, 'I do not like to share resources I create or that I am using because I am worried that people will judge me or think they are not good.', 'I will share resources that I have designed if I am encouraged to and if I feel confident they are good.', 'I am willing to lead professional development in a specific area in which I am comfortable. I am always willing to share things I have designed or that I am doing.', 'I effectively lead peer collaboration and/or professional development (i.e. designing relevant studios, designing rigorous, continua-aligned performance tasks, norming student work, using data to personalize learning for all students). I am always willing to share anything that I have designed or am doing both within and outside of my school.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.7-IND-3', 'TC2.7', 3, 'I do not invite people in to observe my practice and I don''t feel comfortable observing others or giving feedback.', 'I will invite a few trusted individuals in to observe my practice and give me feedback. I am not comfortable giving feedback to others but I do learn from observing others.', 'I invite others in to observe my practice and I am willing to observe my peers or review their instructional design to offer constructive feedback related to their personal and professional goals.', 'I welcome visitors both from within and outside of my school to observe my practice and I am always willing to observe my peers or review their instructional design to offer constructive feedback related to their personal and professional goals.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.8-IND-1', 'TC2.8', 1, 'I am not comfortable and have a fixed mindset when it comes to technology use and I would prefer to only use technology minimally.', 'I am applying a growth mindset to learning how to use all of the required technology (i.e. Google Drive, Slate, PLP) but sometimes I get confused or frustrated.', 'I am comfortable using a variety of technology on a daily basis.', 'I am comfortable using a variety of technology on a daily basis and am constantly seeking new technology to learn myself and to introduce to my students.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC2.8-IND-2', 'TC2.8', 2, 'At the first sign of trouble, I abandon using technology. If I encounter a problem with the technology I am required to use, I don''t try to solve it and I contact someone and wait for them to fix the problem.', 'I have one or two strategies I use when technology fails (i.e. restart, refresh) but often need to reach out for help and support and wait for someone to fix the problem.', 'I try a variety of troubleshooting strategies when technology fails before I reach out for help.', 'I have a variety of troubleshooting strategies I use when technology fails. I know when the problem is one I cannot fix and I know who I need to contact and can confidently explain the problem.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.1-IND-1', 'TC3.1', 1, 'I am working on developing trusting relationships with the students in my advisory.', 'I develop and nurture trusting relationships with the students in my advisory.', 'I develop and nurture relationships with all of the students in my advisory, built on mutual respect, trust, understanding, and empathy.', 'I develop and nurture relationships with and among all of the students in my advisory, built on mutual respect, trust, understanding, and empathy.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.1-IND-2', 'TC3.1', 2, 'I develop individual relationships with some of the students in my advisory to get to know their interests, passions, and goals.', 'I develop individual relationships with most of the students in my advisory to get to know their strengths, challenges, interests, passions, and goals.', 'I develop individual relationships with each student in my advisory to get to know their strengths, challenges, interests, passions, and goals.', 'I develop individual relationships with each student in my advisory to get to know and to support their lives outside of school, their cultural heritages, and their strengths, challenges, interests, passions and goals.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.1-IND-3', 'TC3.1', 3, 'I advocate for students in my advisory when they need my support.', 'I am a strong advocate for each student in my advisory.', 'I am a strong advocate for each student in my advisory and I support them in becoming strong advocates for themselves.', 'I am a strong advocate for each student in my advisory and I support them in becoming strong advocates for themselves and each other.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.1-IND-4', 'TC3.1', 4, 'I am learning how to support the social and emotional growth of my students.', 'I support the social and emotional growth of my students and am learning to be comfortable and sensitive when discussing important and sensitive issues and topics with my students.', 'I support the social and emotional growth of my students and work to create a safe space where most students are comfortable discussing important and sensitive issues and topics.', 'I support the social and emotional growth of my students and work to create a safe space where all students are comfortable discussing important and sensitive issues and topics and where students are comfortable bringing up topics they want or need to discuss.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.2-IND-1', 'TC3.2', 1, 'I have some understanding of the home life of most students in my advisory.', 'I have some understanding of the home life of most students in my advisory and how it impacts their ability to be successful in school.', 'I have a deep understanding of the home life of most students in my advisory and how it impacts their ability to be successful in school.', 'I have a deep understanding of the home life of each student in my advisory and how it impacts their ability to be successful in school.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.2-IND-2', 'TC3.2', 2, 'I build trusting relationships with a few of the families of the students in my advisory.', 'I build trusting relationships with some of the families of the students in my advisory and establish myself as the first point of contact when questions or problems arise.', 'I build trusting relationships with most of the families of the students in my advisory and establish myself as the first point of contact when questions or problems arise.', 'I build trusting relationships with all of the families of the students in my advisory and establish myself as the first point of contact when questions or problems arise.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.2-IND-3', 'TC3.2', 3, 'I have regular communication with the families of students in my advisory who are struggling academically or with behavior and/or attendance.', 'I work with most families to find the best way of establishing proactive and personalized communication to discuss student learning, performance, behavior, attendance, etc.', 'I work with individual families to find the best way of establishing frequent, proactive, and personalized communication to discuss student learning, performance, behavior, attendance, etc.', 'I work with individual families to find the best way of establishing frequent, proactive, and personalized communication to discuss student learning, performance, behavior, attendance, etc. I establish a partnership with families and share strategies that are effective for supporting their student.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.3-IND-1', 'TC3.3', 1, 'I occasionally facilitate community-building and responsive/restorative circles as needed.', 'I facilitate community-building circles at least once per week and responsive/restorative circles as needed.', 'I facilitate community-building circles multiple times per week and responsive/restorative circles as needed. I support students who ask to facilitate community-building circles.', 'I facilitate community-building circles multiple times per week and responsive/restorative circles as needed. I support each of my students in facilitating at least one community-building circle each year.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.3-IND-2', 'TC3.3', 2, 'I design activities for my advisory.', 'I engage my students in decision-making about activities for our advisory.', 'I engage my students in decision-making and encourage them to design and facilitate activities for our advisory.', 'I engage my students in decision-making and most of my students design and facilitate activities for our advisory.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.3-IND-3', 'TC3.3', 3, 'I need to become more comfortable with mindfulness activities before I can use them with my advisory.', 'I occasionally provide opportunities for students to engage in mindfulness activities.', 'I provide regular opportunities for students to engage in mindfulness activities.', 'I provide regular opportunities for students to engage in mindfulness activities and reflection experiences.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.3-IND-4', 'TC3.3', 4, 'I create routines that make our advisory time welcoming and familiar.', 'I create a few rituals and routines that make our advisory time welcoming, familiar, and safe.', 'With some input from the students in my advisory, I create rituals and routines that make our advisory time welcoming, familiar, safe, and special.', 'Together with the students in my advisory, we create rituals and routines that make our advisory time welcoming, familiar, safe, and special.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.4-IND-1', 'TC3.4', 1, 'I am inconsistent in monitoring the academic, attendance, and behavior data for each student in my advisory.', 'I regularly monitor the academic, attendance, and behavior data for each student in my advisory.', 'I consistently and regularly monitor all data (i.e. academic, attendance, behavior, task completion/overdue, academic and personal goals) for each student in my advisory.', 'I consistently and regularly monitor all data (i.e. academic, attendance, behavior, task completion/overdue, academic and personal goals) for each student in my advisory and create systems for me to organize and track success and areas of concern.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.4-IND-2', 'TC3.4', 2, 'When issues arise (e.g. excessive absences, multiple infractions), I sometimes follow up but with little success.', 'When issues arise (e.g. excessive absences, multiple infractions), I seek to understand the cause of the issues and try to intervene to help solve the problem.', 'When issues arise (e.g. excessive absences, multiple infractions), I seek to understand the cause of the issues and try varied interventions to help solve the problem.', 'When issues arise (e.g. excessive absences, multiple infractions), I seek to understand the cause of the issues, try multiple interventions to help solve the problem, and seek additional help and resources if the issues cannot be resolved.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.5-IND-1', 'TC3.5', 1, 'I hold one-to-one conferences with every student in my advisory at least once per learning cycle.', 'I hold one-to-one conferences with every student in my advisory at least once per month.', 'I create a schedule to ensure I regularly hold one-to-one conferences with every student in my advisory multiple times per learning cycle.', 'I create a process or scheduling system to ensure I regularly hold one-to-one conferences with every student in my advisory multiple times per learning cycle and to allow students to sign up for meeting times when they need an additional check-in.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.5-IND-2', 'TC3.5', 2, 'I need support to develop and implement processes, procedures, and/or activities so that students are meaningfully engaged while I run one-to-one conferences.  I am often stopping my conferences to redirect students.', 'I create processes, procedures, and/or activities so that students are meaningfully engaged while I run one-to-one conferences but find that some students are not productively engaged.', 'I create processes, procedures, and/or activities to ensure all students are meaningfully engaged, in small groups or independently, while I run one-to-one conferences.', 'I create processes, procedures, and/or activities to ensure all students are meaningfully engaged, in small groups or independently, while I run one-to-one conferences and students help and support each other so conferences are not interrupted.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.5-IND-3', 'TC3.5', 3, 'I need support or examples to learn how to help my students prepare for one-to-one conferences.', 'I provide my students with a template to use to prepare for one-to-one conferences and support them in completing the template prior to our conference.', 'I create a protocol, template, or system for one-to-one conferences to support students in analyzing and reflecting on the data in their PLP and in setting academic, personal, and career goals.', 'I create a protocol, template, or system for one-to-one conferences to support students in analyzing and reflecting on the data in their PLP, setting academic, personal and career goals and creating and assessing their action plans.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.5-IND-4', 'TC3.5', 4, 'I am learning along with my students how to use systems and digital tools (PLP, task and competency dashboards) to monitor their progress and manage their tasks.', 'I support my students in using systems and digital tools (PLP, task and competency dashboards) to monitor their progress and manage their tasks.', 'I support my students in regularly and effectively using systems and digital tools (PLP, task and competency dashboards) to monitor their own data; manage their tasks; and set, track, and monitor their progress toward academic and personal goals.', 'Students in my advisory take ownership of the use of systems and digital tools (PLP, task and competency dashboards) to regularly monitor their own data, manage their tasks, and set, track, and monitor their progress toward academic and personal goals.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.6-IND-1', 'TC3.6', 1, 'I occasionally provide opportunities for students to self-reflect on the Personal Development competencies and to set goals for their personal growth.', 'I provide opportunities for students to self-reflect on the Personal Development competencies and to set goals for their personal growth at the beginning of the year, mid-year, and at the end of the year.', 'I provide opportunities for students to self-reflect on the Personal Development competencies and to set goals for their personal growth at the beginning of the year and at the end of every learning cycle.', 'I have created a schedule for the year to ensure all of the students in my advisory have the opportunity to self-reflect on the Personal Development competencies and to set goals for their personal growth at regular intervals (i.e., once a month, every six weeks) and I have created a system to track and monitor their growth.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.6-IND-2', 'TC3.6', 2, 'I occasionally provide time for students to reflect on their personal growth and development but struggle to get everyone to participate.', 'I provide time for students to record data and reflect on their personal growth and development.', 'I regularly provide time for students to record data and reflect on their personal growth and development and to get feedback from me.', 'I regularly provide time for students to record data and reflect on their personal growth and development in a variety of ways and to get feedback from me and from their peers.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.6-IND-3', 'TC3.6', 3, 'I am inconsistent in providing enough opportunities for students to evidence (demonstrate mastery of) the Habits of Success competencies.', 'I build in opportunities for students to evidence the Habits of Success competencies and am working on ensuring all students have enough opportunities. I provide everyone with feedback to improve their performance levels and show growth.', 'I consistently build in opportunities for students to evidence the Habits of Success competencies and provide them with regular feedback to reach higher levels on the continuum and show growth for these skills.', 'I consistently build in opportunities for students to evidence the Habits of Success competencies and individually support them in achieving the highest level on the continuum for these skills through regular feedback and conferencing.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.7-IND-1', 'TC3.7', 1, 'I support students in developing a post-secondary plan.', 'I can facilitate a process over time to ensure every student in my advisory has created a realistic and actionable post-secondary plan by the time they graduate from high school.', 'I can facilitate a process over time to ensure every student in my advisory has created a realistic and actionable post-secondary plan by the time they graduate from high school and I help students find some resources to support their post-secondary planning.', 'I can facilitate a process over time to ensure every student in my advisory has created a realistic and actionable post-secondary plan by the time they graduate from high school and I can provide resources and help students in finding resources to support their post-secondary planning.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.7-IND-2', 'TC3.7', 2, 'I provide some opportunities for my students to identify their strengths, interests, and passions.', 'I can provide opportunities and support students in identifying their strengths, interests, and passions and using them to inform their post-secondary planning.', 'I can facilitate a process over time to support students in identifying their strengths, interests, and passions and in choosing a variety of experiences to inform their post-secondary planning.', 'I can facilitate a process over time to help students identify their strengths, interests, and passions; choose different exposure experiences to eliminate options; and to add options previously not considered—all to make the most informed decisions when developing their post-secondary plans.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC3.7-IND-3', 'TC3.7', 3, 'I do not provide feedback to students on resumes, applications, essays, etc.', 'When asked, I provide feedback to students on resumes, applications, essays, etc.', 'I provide feedback to students on resumes, applications, essays, etc. and support them in identifying, tracking, and meeting deadlines and due dates.', 'I provide regular opportunities and make myself available to give feedback and support to students when writing resumes, essays, filling out applications, etc. and I support them in identifying, tracking, and meeting deadlines and due dates.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC4.1-IND-1', 'TC4.1', 1, 'I can situate my performance task within a meaningful context or scenario that is relevant to students.', 'I can design a studio that challenges students to solve a problem or answer a question that is relevant to students.', 'I can design a studio that challenges students to solve a real-world problem or answer a complex question that is highly engaging, interesting, and relevant to students.', 'With input from my students, I can design a studio that challenges students with a complex and authentic problem and question that is highly engaging, interesting, and relevant.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC4.2-IND-1', 'TC4.2', 1, 'I can design performance tasks that address the target competencies and are aligned to the continua for each competency.', 'I can design at least two options from which students can choose for the culminating performance task for my studio in alignment with the target competencies (on the roadmap) that addresses the problem frame of my studio.', 'I can design multiple options from which students can choose for the culminating performance task for my studio. All tasks are in alignment with the target competencies (on the roadmap) and address the problem frame of my studio.', 'I can design multiple options from which students can choose for the culminating performance task for my studio and I can design a structure to support students in designing their own culminating performance task. All tasks are designed in alignment with the target competencies (on the roadmap) and address the problem frame of my studio.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC4.2-IND-2', 'TC4.2', 2, 'I can design performance tasks that require the application of knowledge and skills and that culminate with students demonstrating their learning by creating an answer, product, or performance.', 'I can design at least two options for a culminating performance task that require the application of knowledge and skills and that culminate with students demonstrating their learning by creating an answer, product, or performance for a specific audience.', 'I can design multiple options for culminating performance tasks that require students to create an answer, product, or performance, for an authentic audience and purpose, that demonstrates the application of their knowledge and skills at a high level of complexity, rigor, and authenticity (e.g. Bloom''s ''Creation'', Webb''s DOK 3-4).', 'I can design multiple culminating performance tasks that require students to create an answer, product, or performance, for an authentic audience and purpose, that demonstrates the application of their knowledge and skills at a high level of complexity and rigor, and that closely mirrors the responsibilities of a professional (e.g., artist, engineer, lab technician, consumer advocate, investigative journalist).');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC4.2-IND-3', 'TC4.2', 3, 'The culminating task aligns to one competency in my content area.', 'The culminating task integrates at least two competencies within the same competency area (Reading Critically and Collaborative Discussion).', 'The culminating task effectively integrates two or more competency areas (e.g., ELA and Science, Social Studies and NextGen).', 'The culminating task effectively integrates multiple competency areas (e.g., ELA, Social Studies, and NextGen).');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC4.3-IND-1', 'TC4.3', 1, 'I can clearly communicate the purpose of the performance task and why it is important for students to be able to complete the task.', 'I can clearly communicate the "why" or rationale for the content of this studio.', 'I can clearly communicate the "why" and create a compelling reason for students to engage in the content of this studio.', 'I can clearly communicate the "why" and create a compelling reason for students to engage in the content of this studio to ensure students believe that the content is important and is worth knowing.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC4.3-IND-2', 'TC4.3', 2, 'I can preview the competencies and the continua.', 'I can preview the competencies, continua, and culminating performance task and provide an exemplar.', 'I can preview the competencies, continua, and choices for the culminating performance tasks and provide examples of what success looks like a various levels.', 'I can preview the competencies, continua, and culminating performance tasks, provide examples of what success looks like a various levels, and engage students in using the continua to rate exemplars.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC4.3-IND-3', 'TC4.3', 3, 'I can informally pre-assess students content knowledge and skills (i.e. K-W-L, discussion).', 'I can design short pre-assessments (i.e. quiz, survey) to determine the general knowledge and skill levels of my students related to the content and competencies in my studio.', 'I can design a series of short tasks (cold write, text analysis, self-assessment) to identify individual students'' background knowledge and skill levels related to the content and competencies in my studio.', 'I can design a performance-based prior knowledge assessment to identify individual students'' background knowledge and skill levels related to the content and competencies in my studio.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC4.3-IND-4', 'TC4.3', 4, 'I can preview necessary content and vocabulary.', 'I can design activities to build background, content knowledge, and essential vocabulary.', 'I can design a series of activities where students can engage with one another as well as build curiosity, necessary background and content knowledge, and essential vocabulary.', 'I can design a series of shared experiences and activities, which includes engaging others (experts in the field, community members, those impacted by the problem, etc.), to build curiosity, a deeper understanding of the problem, necessary background and content knowledge, and essential vocabulary.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC4.4-IND-1', 'TC4.4', 1, 'I have limited understanding of the competencies and concepts and need support with the backwards design process.', 'I use my understanding of the competencies and concepts and the backwards design process to design activities aligned to the skills and indicators on the continua.', 'I use my understanding of the competencies and concepts and the backwards design process to design activities aligned to skills and indicators on the continua that strategically build toward the culminating performance task.', 'I use my extensive understanding of the entire Competency Framework and the backwards design process to design activities aligned to skills and indicators on the continua that strategically build to the culminating performance task.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC4.4-IND-2', 'TC4.4', 2, 'I can curate appropriate resources and content to support my students'' investigations.', 'I can curate appropriate and authentic resources and content (i.e. primary source documents and accounts, raw data, research, and publications) to support my students'' investigations.', 'I can curate the most appropriate and authentic resources and content (i.e. primary source documents and accounts, raw data, research, and publications) to support my students'' investigations.', 'I can curate the most appropriate and authentic resources and content (i.e. primary source documents and accounts, raw data, research, and publications) that represent diverse perspectives and viewpoints and I can design tasks for students to curate similar resources related to their problem.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC4.4-IND-3', 'TC4.4', 3, 'I can design a few investigative tasks to engage students in evidence gathering, information and/or data analysis, claim development, and reasoning in order to explore the larger context or scenario of the performance task.', 'I can design a few investigative tasks to engage students in evidence gathering, information and/or data analysis, claim development, and reasoning in order to explore and find solutions to the problem.', 'I can design multiple investigative tasks to ensure students engage in evidence gathering, information and/or data analysis, claim development, and reasoning in order to explore and find solutions to the problem.', 'I can design multiple investigative tasks that expose students to using a specific design process (i.e. design thinking, engineering design, human-centered design) to ensure students engage in evidence gathering, information and/or data analysis, claim development, and reasoning in order to explore and find solutions to the problem.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC4.5-IND-1', 'TC4.5', 1, 'I can facilitate opportunities for students to share their learning (e.g. celebrations of learning, exhibitions, display student work, student work share fair).', 'I can facilitate opportunities for students to share their learning with their intended audience.', 'I can provide my students with the support they need to implement their product or performance in an authentic context (real-world application) to impact their intended audience.', 'I can provide my students with the support they need to implement their product or performance in an authentic context (real-world application) to make a real impact on their intended audience and I can help them find ways to extend their impact (through technology, publishing, presenting at conferences, etc.).');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC4.6-IND-1', 'TC4.6', 1, 'I can establish daily objectives aligned to the skill or concept I am teaching.', 'I can create clear, short-term learning outcomes aligned to the skill or concept being addressed.', 'I can create clear, short-term learning outcomes aligned to the skill or concept being addressed at the appropriate performance level.', 'I can create clear, short-term learning outcomes aligned to the skill or concept being addressed at the appropriate performance level that support the problem frame and culminating task.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC4.6-IND-2', 'TC4.6', 2, 'I sometimes design mini-lessons, learning activities, and tasks aligned to the indicators on the continua.', 'I design mini-lessons, learning activities, and tasks aligned to the skills and indicators on the continua to support skill building.', 'I design targeted mini-lessons, learning activities, and tasks that are aligned to the skills and indicators on the continua and support the intentional building of necessary skills.', 'I design targeted and scaffolded mini-lessons, learning activities, and tasks that are aligned to the skills and indicators on the continua and support the intentional building of necessary skills.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC4.6-IND-3', 'TC4.6', 3, 'I design learning activities that are primarily teacher-led.', 'I can design learning activities that sometimes place the cognitive load on students.', 'I can design learning activities that place the cognitive load on students and incorporate student voice and choice.', 'I consistently design learning activities that place the cognitive load on students and incorporate student voice and choice at high levels of autonomy.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC4.6-IND-4', 'TC4.6', 4, 'I select texts based on what is most familiar to me.', 'I can select text at the appropriate level for the grade level I am teaching.', 'I can select text at the appropriate level of quantitative and qualitative complexity for my students that represents diverse perspectives.', 'I can select text at the appropriate level of qualitative and quantitative complexity for my students that represents diverse writers, perspectives, viewpoints, beliefs, and cultures.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC4.6-IND-5', 'TC4.6', 5, 'I can design formative assessments to assess student learning.', 'I can design multiple types of formative assessments to assess student learning.', 'I can design multiple and varied types of formative assessments to assess student learning and to inform my instructional design.', 'I can design multiple and varied types of formative assessments and I choose the type of formative assessment that will give me the specific data I need to evaluate my students'' understanding of skills and content and to inform my instructional design.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC4.6-IND-6', 'TC4.6', 6, 'I use at least one type of data in addition to my formative assessments to inform my instruction.', 'I analyze multiple forms of data (task completion, formative assessments, competency ratings, standardized assessments) to make real-time instructional adjustments.', 'I regularly analyze multiple forms of data (task completion, formative assessments, competency ratings, standardized assessments) to make real-time instructional adjustments and to modify student groupings.', 'I regularly analyze multiple forms of data (task completion, formative assessments, competency ratings, standardized assessments) to determine progress toward intended outcomes, to make real-time instructional adjustments, and to modify student groupings.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.1-IND-1', 'TC5.1', 1, 'I need support to develop and implement clear routines and procedures to create and to maintain a safe physical and intellectual environment.', 'I sometimes use routines, procedures, and proactive responses to create and maintain a safe physical and intellectual environment.', 'I use consistent routines, procedures, and proactive responses to create and maintain a safe physical and intellectual environment where students take academic risks and seek help when needed.', 'I use consistent rituals, routines, procedures, and proactive responses to create and maintain a safe physical and intellectual environment where learning time is maximized and students feel comfortable taking academic risks and seeking help when needed.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.1-IND-2', 'TC5.1', 2, 'I am working on my responses to behaviors that interfere with learning. I sometimes get frustrated and am not as effective as I could be in creating an environment of respect and rapport.', 'I create and maintain an environment of respect and rapport that results in some students engaging in respectful interactions with adults and peers.', 'I create an environment of respect and rapport that results in most students engaging in respectful interactions with adults and peers and where most behaviors that interfere with learning are prevented.', 'I create and maintain an environment of respect and rapport that results in all students engaging in respectful interactions with adults and peers and playing an active role—individually and collectively— in preventing behaviors that interfere with learning.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.1-IND-3', 'TC5.1', 3, 'I develop relationships with some students but struggle to connect with all students.', 'I develop and sustain relationships with many students who are actively engaged in learning and I am trying to build relationships with the students with whom I have not yet connected.', 'I develop and sustain relationships with most of my students and most students are actively engaged in the learning process.', 'I develop and sustain relationships with my students that result in high levels of active student engagement in the learning process.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.1-IND-4', 'TC5.1', 4, 'My learning space is visually inviting, clean, and organized.', 'My learning space is visually inviting, clean, and organized and flexible.', 'My learning space is visually inviting, clean, and organized and is arranged to support a variety of different learning tasks, student groupings, and different learners.', 'My learning space is visually inviting, clean, and organized and is arranged to support a variety of different learning tasks and different learners. I can easily reconfigure my learning environment to best meet the task at hand.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.2-IND-1', 'TC5.2', 1, 'I ensure that most students understand the task(s) and competencies on which they are working .', 'I ensure that every student understands on which task(s) and competencies they are working and on what level of the continua they need to achieve.', 'I ensure that every student understands on which task(s) and competencies they are working and on what level of the continua they need to achieve. I consistently reinforce why the task is relevant.', 'I ensure that every student understands on which task(s) and competencies they are working and on what level of the continua they need to achieve. I consistently reinforce why the task is relevant and how the learning is connected to the larger problem frame.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.2-IND-2', 'TC5.2', 2, 'I review and explain the continua for each competency on which students are working and ensure they have access to all of the needed continua.', 'I review and explain the continua for each competency on which students are working, ensure they have access to all of the needed continua and provide at least one exemplar for each task.', 'I review and explain the continua for each competency on which students are working, ensure they have access to all of the needed continua and I provide exemplars of what success looks like at different levels on the continua.', 'I review and explain the continua for each competency on which students are working, ensure they have access to all of the needed continua and I provide annotated exemplars of what success looks like at different levels on the continua for every task.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.2-IND-3', 'TC5.2', 3, 'I sometimes use formative assessments (e.g. self-assessment, exit tickets, student surveys) to ensure students have gained the necessary skills and knowledge.', 'I sometimes use formative assessments (e.g. self-assessment, exit tickets, student surveys) in a timely manner to monitor learner progress, guide my decision making and instructional practice, and ensure students have gained the necessary skills and knowledge to complete the performance-based assessments.', 'I use frequent formative assessments (e.g. self-assessment, exit tickets, student surveys) in a timely manner to monitor learner progress, guide my decision making and instructional practice, and ensure students have gained the necessary skills and knowledge to complete the performance-based assessments at the desired level on the continua.', 'I use multiple, varied and frequent formative assessments (e.g. self-assessment, exit tickets, student surveys) in a timely manner to engage learners in their own growth, monitor learner progress, guide my decision making and instructional practice, and ensure students have gained the necessary skills and knowledge to complete the performance-based assessments at the desired level on the continua.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.3-IND-1', 'TC5.3', 1, 'I present concepts that engage learners and sometimes invite students to think deeply about the content.', 'I present concepts that engage learners in critical thinking.', 'I present concepts that draw on material from diverse writers, perspectives, and viewpoints in order to engage learners in critical thinking.', 'I present concepts both within and across disciplines that draw on material from diverse writers, perspectives, and viewpoints in order to engage learners in critical thinking.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.3-IND-2', 'TC5.3', 2, 'I communicate concepts within my content that are of interest to me.', 'I communicate concepts associated with my content area(s). Some are critical to the subject-matter while others are of interest to me.', 'I communicate key concepts associated with my content area(s) (e.g. Algebra teachers need to know which concepts are necessary for college and career readiness, which are foundational, which are more complex, and how to explain the math in multiple ways).', 'I communicate key concepts associated with my content area(s) (e.g. Algebra teachers need to know which concepts are necessary for college and career readiness, which are foundational, which are more complex, and how to explain the math in multiple ways) and I use my knowledge of learning progressions in order to build students’ solid understanding of the content I want them to learn.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.3-IND-3', 'TC5.3', 3, 'I engage students in learning activities and discussions about content mostly to see if they can recall the content I have taught.', 'I sometimes engage students in challenging and high quality content through learning activities and discussions that require higher level thinking.', 'I engage students in challenging and high quality content through learning activities and discussions that require higher level thinking and identifying and addressing misconceptions as they arise.', 'I engage students in challenging and high quality content through learning activities and discussions that require complex and higher level thinking and identifying and addressing misconceptions as they arise.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.3-IND-4', 'TC5.3', 4, 'I am inconsistent in providing all students opportunities to collaborate.', 'I provide students with a few opportunities to collaborate.', 'I create opportunities for students to work together to focus on some of the essential skills of collaboration (i.e. listening, understanding different perspectives, working together, managing conflict).', 'I create multiple opportunities for students to work together to build the essential skills of collaboration (i.e. listening, understanding different perspectives, working together, managing conflict).');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.3-IND-5', 'TC5.3', 5, 'I focus on how students apply their learning (products of thinking) rather than on the process of thinking.', 'I use think alouds to model my process of thinking (metacognItion).', 'I use modeling (think alouds and annotation), rehearsal (guided practice), and feedback techniques that highlight the processes of thinking (metacognition) rather than focusing exclusively on the products of thinking.', 'I use modeling (think alouds and annotation), rehearsal (guided practice), and feedback techniques that highlight the processes of thinking (metacognition) rather than focusing exclusively on the products of thinking and provide opportunities for students to reflect on and discuss their own thinking.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.3-IND-6', 'TC5.3', 6, 'I ask questions to check for comprehension, understanding, and recall of the content I have taught.', 'I ask questions that check for recall and understanding but also include some higher level questions that require analysis and evaluation.', 'I ask questions that require analysis, evaluation and challenging each other''s thinking.', 'I ask questions and teach students to ask questions that require analysis, evaluation and challenging each other''s thinking.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.4-IND-1', 'TC5.4', 1, 'I set and maintain high expectations for achievement for some of my students.', 'I set high expectations for achievement for all of my students, but sometimes have difficulty maintaining those expectations.', 'I set and maintain explicit and high expectations for achievement for all of my students and support my students in reaching common learning goals at a variety of levels.', 'I set and maintain explicit and high expectations for achievement for all of my students while designing multiple and varied pathways for my students to reach common learning goals at a variety of levels.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.4-IND-2', 'TC5.4', 2, 'I need support to address specific differences in individual students’ learning needs, abilities, styles, interests, cultures, and levels of readiness.', 'I use a few teaching strategies to address specific differences in individual students’ learning needs, abilities, styles, interests, cultures, and levels of readiness.', 'I use several  different teaching strategies to address specific differences in individual students’ learning needs, abilities, styles, interests, cultures, and levels of readiness.', 'I use a variety of teaching strategies, such as tiered supports and scaffolded instruction, to address specific differences in individual students’ learning needs, abilities, styles, interests, cultures, and levels of readiness.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.4-IND-3', 'TC5.4', 3, 'I need support in order to understand how to address learning gaps while teaching grade level content.', 'I scaffold instruction so that most learners can master the content and skills and fill in gaps in understanding.', 'I scaffold instruction so that all learners can master the content and skills and fill in gaps in understanding.', 'I customize and scaffold instruction, supports, and pacing so that all learners can master the content and skills and fill in gaps in understanding.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.4-IND-4', 'TC5.4', 4, 'I mostly teach whole class lessons then have students work independently on what I taught.', 'I minimally adjust student groupings (e.g. whole group, small group, collaborative projects, one-to-one conferences) to accommodate the different learning needs of my students.', 'I sometimes vary student groupings (e.g. whole group, small group, collaborative projects, one-to-one conferences) to accommodate the different learning needs of my students.', 'I consistently vary student groupings (e.g. whole group, small group, collaborative projects, one-to-one conferences) to accommodate the different learning needs of my students.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.4-IND-5', 'TC5.4', 5, 'I am not sure how to adapt my instruction, materials, and assessments to make challenging material accessible to all students, including English language learners and students with disabilities and I need support to do this effectively.', 'I try to adapt instruction, materials, and assessments to make challenging material accessible to all students, including English language learners and students with disabilities, but I am sometimes unsure of the best way to do that while still maintaining high expectations.', 'On my own and together with my colleagues, I adapt instruction, materials, and assessments to make challenging material accessible to all students, including English language learners and students with disabilities, while still maintaining high expectations.', 'I consistently adapt instruction, materials, and assessments to make challenging material accessible to all students, including English language learners and students with disabilities, while still maintaining high expectations.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.5-IND-1', 'TC5.5', 1, 'I assign topics and tasks to students and will occasionally provide my students with choice by providing them with one or two options for topics or for how they demonstrate their learning.', 'I provide my students with cognitive choice by involving them in making decisions about the topics they are learning about.', 'I provide my students with cognitive choice by involving them in making decisions about the topics they are learning about and how they demonstrate their learning.', 'I provide my students with cognitive choice by involving them in making decisions about how and where they learn, the topics they are learning about, and how they demonstrate their learning.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.5-IND-2', 'TC5.5', 2, 'I usually have students working at the same pace and occasionally will allow a few students to work ahead.', 'I encourage students to work at their own pace and begin to take some ownership of their learning.', 'I create a learning environment that builds students’ ability to engage in self-paced learning, and that encourages students to take ownership of their learning.', 'I create a learning environment that builds students’ ability to engage in self-directed and self-paced learning, and that encourages students to take ownership of their learning.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.6-IND-1', 'TC5.6', 1, 'I am inconsistent in my expectations for work quality and sometimes accept work that I rate very low on the continua.', 'I expect quality work from my students but sometimes do not require students to revise their work.', 'I consistently demonstrate high expectations for the quality of student work and require students to engage in more than one round of revision if the task does not meet the expectations of their performance level.', 'I consistently demonstrate high expectations for the quality of student work and the perseverance and effort required to produce it, and require students to engage in several rounds of revision if the task does not meet the expectations of their performance level.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.6-IND-2', 'TC5.6', 2, 'I encourage my students to go through at least one revision cycle for each task.', 'I encourage my students to set high expectations for themselves to raise their performance levels by completing at least one feedback and revision cycle for each task.', 'I encourage my students to set high expectations for themselves to produce high-quality work through multiple feedback and revision cycles.', 'I encourage students to set high expectations for themselves and for each other to produce high-quality work through multiple feedback and revision cycles.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.6-IND-3', 'TC5.6', 3, 'I give most of my students continua-based feedback before they submit their final performance task(s).', 'I give continua-based feedback to most of my students throughout the learning cycle.', 'I give timely and actionable continua-based feedback to all of my students throughout the learning cycle.', 'I give timely, specific, and actionable continua-based feedback to all of my students multiple times throughout the learning cycle.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.7-IND-1', 'TC5.7', 1, 'I am inconsistent in my use of the task dashboard and the competency dashboard and do not always keep up with rating student work, marking tasks complete, and/or sending tasks back for revision.', 'I consistently use the task dashboard and the competency dashboard to manage student tasks. I am working to be more consistent in providing timely ratings and feedback.', 'I consistently use the task dashboard and the competency dashboard to manage student tasks, provide timely ratings, and opportunities for revision and feedback.', 'I consistently use the task dashboard and the competency dashboard to manage and differentiate student tasks, provide timely ratings, and opportunities for of revision and feedback.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.7-IND-2', 'TC5.7', 2, 'I am inconsistent in my use of systems to track student behavior, attendance, and voice (i.e. student log, studio attendance, ensuring all students take surveys).', 'I am fairly consistent in my use of systems to track student behavior, attendance, and voice (i.e. student log, studio attendance, ensuring all students take surveys).', 'I am consistent in my use of systems to track student behavior, attendance, and voice (i.e. student log, studio attendance, ensuring all students take surveys) ensuring that I track all infractions, provide students with shout-outs, take daily attendance, and have high completion rates for student surveys.', 'I consistently and routinely use systems to track student behavior, attendance, and voice (i.e. student log, studio attendance, ensuring all students take surveys) ensuring that I track all infractions, provide students with shout-outs often, take daily attendance, and have high completion rates for student surveys as well as creating ways to gain information from students about other factors that are important to their success (i.e. interest, engagement, relationships).');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.7-IND-3', 'TC5.7', 3, 'I use objective data that has been collected and organized for me (i.e. student voice, behavior, attendance, competency progress, and standardized assessments) to inform my instructional practice.', 'I organize and analyze objective data from a few sources (i.e. student voice, behavior, attendance, competency progress, and standardized assessments).  I use that data to inform my instructional practice.', 'I collect, organize, and analyze objective data from multiple sources, including student voice, behavior, attendance, competency progress, and standardized assessments. I use that data to inform my instructional practice and to help me reflect on and improve my practice.', 'I collect, organize, and analyze objective data from multiple sources, including student voice, behavior, attendance, competency progress, and standardized assessments. I draw appropriate and actionable conclusions to inform short and long-term instructional decisions and to help me reflect on and improve my practice.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.7-IND-4', 'TC5.7', 4, 'I use tools when I am instructed to during professional development (progress look-up, student and teacher PLPs, competency and task dashboards) to identify which students are not on track for portfolio completion and the reasons why.', 'I occasionally use tools (progress look-up, student and teacher PLPs, competency and task dashboards) to identify which students are not on track for portfolio completion and the reasons why and use that information to modify my instruction and supports for those students.', 'I regularly use tools (progress look-up, student and teacher PLPs, competency and task dashboards) to understand individual skills, gaps, strengths and weaknesses of each student, and use that information to create additional opportunities to ensure my students meet performance level and growth targets, complete their portfolios and accelerate when appropriate.', 'I regularly and systematically use tools (progress look-up, student and teacher PLPs, competency and task dashboards) to understand individual skills, gaps, strengths, weaknesses, interests, and aspirations of each student, and use that information to design and modify personalized learning pathways toward meeting performance level and growth targets, completing portfolios and accelerating whenever possible.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.8-IND-1', 'TC5.8', 1, 'I mostly use technology to replace non-digital tools (i.e digital worksheets, digital agendas, digital assignments, etc.)', 'I use technology as an effective tool to perform common tasks more efficiently (i.e. exit ticket or survey using Google Form).', 'I require technology use on a regular basis to enhance teaching, learning, and student impact (i.e. teacher and peer feedback, audio recordings, multimedia presentations).', 'I require technology use on a regular basis to enhance teaching, learning, and student impact and I support my students in using technology to create tasks and products that would otherwise not be possible (i.e. website published, documentary publication, app creation).');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.8-IND-2', 'TC5.8', 2, 'I mostly rely on my students to use digital tools and websites they are familiar with, but am unable to monitor or support them in their use.', 'I expose students to a few digital tools I am comfortable using and a few websites I know are safe and accurate for information gathering.', 'I promote the development of “digital fluency” in my students by exposing them to a variety of digital tools for different purposes.', 'I promote the development of “digital fluency” in my students by supporting them in choosing the most appropriate tools and technologies for the task and in understanding why they are the best choice.');
INSERT OR REPLACE INTO framework_indicators (id, competency_id, indicator_index, rubric_stage1, rubric_stage2, rubric_stage3, rubric_stage4) VALUES ('TC5.8-IND-3', 'TC5.8', 3, 'I use digital resources that have been created and I am learning how to adapt them appropriately.', 'I often adapt high-quality digital resources or use ones that have already been created. I try to create my own digital resources but the quality is inconsistent.', 'I regularly create and adapt high-quality digital resources.', 'I consistently create and adapt high-quality Google site studios and digital resources.');
